  </div>
</nav>

<!-- ═══════════════════════ MAIN CONTENT ═══════════════════════ -->
<main id="main-content">

  <!-- ─── HERO ─── -->
  <section class="hero" aria-labelledby="hero-title">
    <div class="container">
      <div class="hero__inner">
        <div class="hero__content">
          <div class="hero__badge" aria-label="Free for patients">
            <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true">
              <path d="M6 1l1.2 2.4L10 4.2l-2 1.9.5 2.7L6 7.5 3.5 8.8l.5-2.7-2-1.9 2.8-.8L6 1z" fill="currentColor"/>
            </svg>
            Free for patients — always
          </div>
          <h1 class="hero__title" id="hero-title">
            Find and book the<br /><em>care you need</em>
          </h1>
          <p class="hero__subtitle">
            Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.
          </p>

          <!-- Search Box -->
          <div class="search-box" role="search" aria-label="Find a doctor">
            <div class="search-box__fields">
              <!-- Field 1: Specialty -->
              <div class="search-field" style="position:relative;">
                <span class="search-field__icon" aria-hidden="true">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <path d="M21 21l-4.35-4.35M17 11A6 6 0 1 1 5 11a6 6 0 0 1 12 0z" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                  </svg>
                </span>
                <label class="search-field__label" for="search-specialty">Specialty / Condition</label>
                <input
                  id="search-specialty"
                  class="search-field__input"
                  type="text"
                  placeholder="Dentist, back pain, Dr. Chen…"
                  autocomplete="off"
                  aria-autocomplete="list"
                  aria-controls="autocomplete-list"
                  aria-expanded="false"
                  role="combobox"
                />
                <ul id="autocomplete-list" class="autocomplete-dropdown" role="listbox" aria-label="Suggestions">
                  <li role="option" aria-selected="false">
                    <button class="autocomplete-item" type="button">
                      <span class="autocomplete-item__icon" aria-hidden="true">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><rect x="3" y="3" width="18" height="18" rx="3" stroke="currentColor" stroke-width="2"/><path d="M12 8v8M8 12h8" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
                      </span>
                      <span>
                        <span class="autocomplete-item__label">Primary Care Doctor</span>
                        <span class="autocomplete-item__type" style="display:block">Specialty</span>
                      </span>
                    </button>
                  </li>
                  <li role="option" aria-selected="false">
                    <button class="autocomplete-item" type="button">
                      <span class="autocomplete-item__icon" aria-hidden="true">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="9" stroke="currentColor" stroke-width="2"/><path d="M12 7v5l3 3" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
                      </span>
                      <span>
                        <span class="autocomplete-item__label">Dentist</span>
                        <span class="autocomplete-item__type" style="display:block">Specialty</span>
                      </span>
                    </button>
                  </li>
                  <li role="option" aria-selected="false">
                    <button class="autocomplete-item" type="button">
                      <span class="autocomplete-item__icon" aria-hidden="true">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M4.5 6.375a4.125 4.125 0 118.25 0 4.125 4.125 0 01-8.25 0zM14.25 8.625a3.375 3.375 0 116.75 0 3.375 3.375 0 01-6.75 0z" stroke="currentColor" stroke-width="1.5"/></svg>
                      </span>
                      <span>
                        <span class="autocomplete-item__label">Dermatologist</span>
                        <span class="autocomplete-item__type" style="display:block">Specialty</span>
                      </span>
                    </button>
                  </li>
                  <li role="option" aria-selected="false">
                    <button class="autocomplete-item" type="button">
                      <span class="autocomplete-item__icon" aria-hidden="true">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M9 12.75L11.25 15 15 9.75" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="12" cy="12" r="9" stroke="currentColor" stroke-width="2"/></svg>
                      </span>
                      <span>
                        <span class="autocomplete-item__label">Back Pain</span>
                        <span class="autocomplete-item__type" style="display:block">Condition</span>
                      </span>
                    </button>
                  </li>
                  <li role="option" aria-selected="false">
                    <button class="autocomplete-item" type="button">
                      <span class="autocomplete-item__icon" aria-hidden="true">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="8" r="4" stroke="currentColor" stroke-width="2"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
                      </span>
                      <span>
                        <span class="autocomplete-item__label">Dr. Sarah Chen</span>
                        <span class="autocomplete-item__type" style="display:block">Provider</span>
                      </span>
                    </button>
                  </li>
                </ul>
              </div>

              <!-- Field 2: Location -->
              <div class="search-field">
