<script>
  // ─── Mobile Drawer ───
  const hamburgerBtn = document.getElementById('hamburger-btn');
  const drawerCloseBtn = document.getElementById('drawer-close-btn');
  const drawerOverlay = document.getElementById('drawer-overlay');
  const drawer = document.getElementById('mobile-drawer');

  function openDrawer() {
    document.body.classList.add('drawer-open');
    hamburgerBtn.setAttribute('aria-expanded', 'true');
    drawer.setAttribute('aria-hidden', 'false');
    drawerOverlay.setAttribute('aria-hidden', 'false');
    drawerCloseBtn.focus();
  }

  function closeDrawer() {
    document.body.classList.remove('drawer-open');
    hamburgerBtn.setAttribute('aria-expanded', 'false');
    drawer.setAttribute('aria-hidden', 'true');
    drawerOverlay.setAttribute('aria-hidden', 'true');
    hamburgerBtn.focus();
  }

  hamburgerBtn.addEventListener('click', openDrawer);
  drawerCloseBtn.addEventListener('click', closeDrawer);
  drawerOverlay.addEventListener('click', closeDrawer);

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && document.body.classList.contains('drawer-open')) {
      closeDrawer();
    }
  });

  // Close drawer on nav link click
  drawer.querySelectorAll('.drawer__link, .drawer__actions .btn').forEach(link => {
    link.addEventListener('click', closeDrawer);
  });

  // ─── Autocomplete ───
  const searchInput = document.getElementById('search-specialty');
  const autocompleteList = document.getElementById('autocomplete-list');

  const suggestions = [
    { label: 'Primary Care Doctor', type: 'Specialty' },
    { label: 'Dentist', type: 'Specialty' },
    { label: 'Dermatologist', type: 'Specialty' },
    { label: 'Psychiatrist', type: 'Specialty' },
    { label: 'Eye Doctor', type: 'Specialty' },
    { label: 'Orthopedic Surgeon', type: 'Specialty' },
    { label: 'Back Pain', type: 'Condition' },
    { label: 'Anxiety & Depression', type: 'Condition' },
    { label: 'Skin Rash', type: 'Condition' },
    { label: 'Dr. Sarah Chen', type: 'Provider' },
    { label: 'Dr. Marcus Rivera', type: 'Provider' },
  ];

  function renderSuggestions(query) {
    const filtered = query.length < 1
      ? []
      : suggestions.filter(s => s.label.toLowerCase().includes(query.toLowerCase()));

    autocompleteList.innerHTML = '';

    if (filtered.length === 0) {
      autocompleteList.classList.remove('is-open');
      searchInput.setAttribute('aria-expanded', 'false');
      return;
    }

    filtered.forEach((s, i) => {
      const li = document.createElement('li');
      li.setAttribute('role', 'option');
      li.setAttribute('aria-selected', 'false');
      li.innerHTML = `
        <button class="autocomplete-item" type="button" data-value="${s.label}">
          <span class="autocomplete-item__icon" aria-hidden="true">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M21 21l-4.35-4.35M17 11A6 6 0 1 1 5 11a6 6 0 0 1 12 0z" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
          </span>
          <span>
            <span class="autocomplete-item__label">${s.label}</span>
            <span class="autocomplete-item__type" style="display:block">${s.type}</span>
          </span>
        </button>
      `;
      li.querySelector('button').addEventListener('click', () => {
        searchInput.value = s.label;
        autocompleteList.classList.remove('is-open');
        searchInput.setAttribute('aria-expanded', 'false');
        searchInput.focus();
      });
      autocompleteList.appendChild(li);
    });

    autocompleteList.classList.add('is-open');
    searchInput.setAttribute('aria-expanded', 'true');
  }

  let debounceTimer;
  searchInput.addEventListener('input', e => {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => renderSuggestions(e.target.value), 120);
  });

  searchInput.addEventListener('focus', e => {
    if (e.target.value.length > 0) renderSuggestions(e.target.value);
  });

  document.addEventListener('click', e => {
    if (!e.target.closest('.search-field')) {
      autocompleteList.classList.remove('is-open');
      searchInput.setAttribute('aria-expanded', 'false');
    }
  });

  // Keyboard nav for autocomplete
  searchInput.addEventListener('keydown', e => {
    const items = autocompleteList.querySelectorAll('.autocomplete-item');
    if (!items.length) return;
    let activeIdx = Array.from(items).findIndex(i => i.closest('[aria-selected="true"]'));

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      activeIdx = (activeIdx + 1) % items.length;
      items.forEach((i, idx) => i.closest('[role="option"]').setAttribute('aria-selected', idx === activeIdx ? 'true' : 'false'));
      items[activeIdx].focus();
    } else if (e.key === 'Escape') {
      autocompleteList.classList.remove('is-open');
      searchInput.setAttribute('aria-expanded', 'false');
    } else if (e.key === 'Enter') {
      if (activeIdx >= 0) items[activeIdx].click();
    }
  });

  // ─── Time Slot Toggle ───
  document.querySelectorAll('.time-slot').forEach(slot => {
    slot.addEventListener('click', function() {
      this.closest('.time-slots').querySelectorAll('.time-slot').forEach(s => {
        s.classList.remove('selected');
        s.setAttribute('aria-pressed', 'false');
      });
      this.classList.add('selected');
      this.setAttribute('aria-pressed', 'true');
    });
  });

  // ─── Smooth scroll for anchor links ───
  document.querySelectorAll('a[href^="#"]').forEach(a => {
    a.addEventListener('click', e => {
      const target = document.querySelector(a.getAttribute('href'));
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });
</script>

</body>
